"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";

import { Page } from "@/types";

export default function DashboardPage() {
  const [pages, setPages] = useState<Page[]>([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();

  useEffect(() => {
    fetchPages();
  }, []);

  async function fetchPages() {
    try {
      const res = await fetch("/api/pages");
      const data = await res.json();
      setPages(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error("Failed to fetch pages:", err);
    } finally {
      setLoading(false);
    }
  }

  async function deletePage(id: string) {
    if (!confirm("Are you sure you want to delete this page?")) return;
    await fetch(`/api/pages/${id}`, { method: "DELETE" });
    fetchPages();
  }

  function formatDate(dateStr: string) {
    return new Date(dateStr).toLocaleDateString("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  }

  const publishedCount = pages.filter((p) => p.status === "published").length;
  const draftCount = pages.filter((p) => p.status === "draft").length;

  return (
    <div className="flex flex-col flex-1 w-full">

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-6 py-8 w-full flex-1 space-y-8">
        {/* Welcome & Stats Banner */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-6 border-b border-border/60">
          <div>
            <h2 className="text-2xl font-extrabold text-foreground tracking-tight">
              Dashboard Overview
            </h2>
            <p className="text-sm text-muted mt-1">
              System health, active database pages, and CMS state.
            </p>
          </div>

          <div className="flex items-center gap-3">
            <Link
              href="/webpages"
              className="px-4 py-2 bg-card hover:bg-card-hover border border-border text-foreground text-xs font-semibold rounded-xl transition-all flex items-center gap-2"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
              View Webpages ({pages.length})
            </Link>
          </div>
        </div>

        {/* Metrics Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div className="p-5 bg-card border border-border rounded-2xl shadow-sm space-y-1">
            <div className="text-xs font-semibold text-muted uppercase tracking-wider">
              Total DB Pages
            </div>
            <div className="text-3xl font-black text-foreground">
              {loading ? "..." : pages.length}
            </div>
            <div className="text-xs text-muted/80">Stored in PostgreSQL</div>
          </div>

          <div className="p-5 bg-card border border-border rounded-2xl shadow-sm space-y-1">
            <div className="text-xs font-semibold text-muted uppercase tracking-wider">
              Published Pages
            </div>
            <div className="text-3xl font-black text-success">
              {loading ? "..." : publishedCount}
            </div>
            <div className="text-xs text-muted/80">Live on main site</div>
          </div>

          <div className="p-5 bg-card border border-border rounded-2xl shadow-sm space-y-1">
            <div className="text-xs font-semibold text-muted uppercase tracking-wider">
              Draft Pages
            </div>
            <div className="text-3xl font-black text-accent">
              {loading ? "..." : draftCount}
            </div>
            <div className="text-xs text-muted/80">Unpublished drafts</div>
          </div>
        </div>

        {/* Recent Pages Section */}
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-base font-bold text-foreground">
              Recent Database Pages
            </h3>
            <Link
              href="/webpages"
              className="text-xs font-semibold text-accent hover:underline"
            >
              See all webpages &rarr;
            </Link>
          </div>

          {loading ? (
            <div className="p-8 text-center text-muted text-sm bg-card border border-border rounded-2xl">
              Loading pages from database...
            </div>
          ) : pages.length === 0 ? (
            <div className="text-center py-16 bg-card border border-border rounded-2xl p-6">
              <div className="w-12 h-12 rounded-2xl bg-border/40 text-muted flex items-center justify-center mx-auto mb-3">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M13 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"/><polyline points="13 2 13 9 20 9"/></svg>
              </div>
              <div className="text-foreground font-semibold text-base mb-1">No pages found in database</div>
              <p className="text-muted text-xs max-w-sm mx-auto">
                No pages have been saved to the PostgreSQL database yet.
              </p>
            </div>
          ) : (
            <div className="space-y-3">
              {pages.slice(0, 5).map((page) => (
                <div
                  key={page.id}
                  className="flex items-center justify-between p-4 bg-card border border-border rounded-2xl hover:bg-card-hover transition-all group"
                >
                  <div
                    className="flex-1 cursor-pointer"
                    onClick={() => router.push(`/editor/${page.id}`)}
                  >
                    <div className="flex items-center gap-3">
                      <h4 className="font-semibold text-foreground text-sm group-hover:text-accent transition-colors">
                        {page.title}
                      </h4>
                      <span
                        className={`text-[10px] px-2.5 py-0.5 rounded-full font-bold uppercase tracking-wider ${
                          page.status === "published"
                            ? "bg-success/10 text-success border border-success/20"
                            : "bg-accent/10 text-accent border border-accent/20"
                        }`}
                      >
                        {page.status}
                      </span>
                    </div>
                    <p className="text-xs text-muted mt-1">
                      /{page.slug} &bull; Updated {formatDate(page.updatedAt)}
                    </p>
                  </div>

                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => router.push(`/editor/${page.id}`)}
                      className="px-3.5 py-1.5 text-xs font-semibold text-foreground bg-background border border-border rounded-xl hover:bg-card-hover transition-colors shadow-sm"
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => deletePage(page.id)}
                      className="px-3.5 py-1.5 text-xs font-semibold text-danger bg-danger/10 border border-danger/20 rounded-xl hover:bg-danger/20 transition-colors"
                    >
                      Delete
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}
